style.css:
@-moz-document domain("open.spotify.com") {
body::after {
    content: "";
    position: fixed;
    bottom: 20px;
    right: 20px;
    width: 100px;
    height: 100px;
    border-radius: 50%;
    background-image: url("https://i.imgur.com/2W4E3J6.png");
    background-size: cover;
    background-position: center;
    border: 3px solid #1DB954;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.5);
    z-index: 9999;
    pointer-events: none;
  }
}
